CREATE TABLE IF NOT EXISTS cutover_identity_proof(entry varchar(64) COLLATE utf8mb4_bin NOT NULL,legacy_id varchar(128) COLLATE utf8mb4_bin NOT NULL,user_id varchar(64) COLLATE utf8mb4_bin NOT NULL,route_slot char(6) NOT NULL,effect_kind varchar(16) NOT NULL,biz_type varchar(32) NOT NULL,biz_id varchar(128) COLLATE utf8mb4_bin NOT NULL,request_hash char(64) NOT NULL,receipt json NOT NULL,PRIMARY KEY(entry,legacy_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
